    startsAt: brandStamp(row.startsAt),
    endsAt: brandStamp(row.endsAt),
    note: row.note,
  };
}

export function toInvitation(row: InvitationRow): Invitation {

/**
 * Out-of-office rows. One per member per workspace; every query is org-scoped.
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { SetAbsenceInput } from "@/schemas/member";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Inserts the absence, or replaces the whole row when one is already stored. */
export async function upsertAbsence(
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  const values = {
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  };
  const row = getDb()
    .insert(memberAbsences)
    .values(values)
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: values.delegateUserId,
        startsAt: values.startsAt,
        endsAt: values.endsAt,
        note: values.note,
      },
    })
    .returning()
    .get();
  return toMemberAbsence(row);
}

/** Deleting a missing row is a no-op. */
export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Drops this user as anyone else's stand-in in the workspace. The absences
 * stay, now with no delegate, so work is never sent to someone who left.
 */
export async function clearDelegateReferences(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

