/**
 * Membership and role changes, including the invariant that an organization always keeps one owner.
 *
 * Out-of-office absences live here too: who may set them, and which stand-in
 * (if any) is covering a member at a given instant.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import {
  actorEnvelope,
  memberResource,
  NotFoundError,
  orgResource,
  requireFound,
} from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  SetAbsenceInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type {
  Actor,
  Member,
  MemberAbsence,
  MemberWithUser,
  Role,
} from "@/types/member";

const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

// The absence leaves with the member. Anyone they were covering keeps the
// absence, but no longer points at a person who has left the workspace.
await absenceRepo.deleteAbsence(input.orgId, removed.userId);
await absenceRepo.clearDelegateReferences(input.orgId, removed.userId);

await emit("member.removed", {

