input.new_string:
  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

/**
 * Stores an out-of-office window, replacing any absence already stored for
 * this member in this workspace. The end is exclusive and must be after the
 * start. A delegate, when named, is another active member of the same
 * workspace.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  assertAbsenceWindow(input.startsAt, input.endsAt);

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    ...input,
    delegateUserId,
    note: input.note ?? null,
  });
}

/** Removes the stored absence. Clearing when none is set is a no-op. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence while it has not ended, including one that has not
 * started yet. `null` once it has ended or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));
  await requireActiveMember(orgId, userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence) return null;

  const end = new Date(absence.endsAt).getTime();
  if (!Number.isFinite(end) || end <= Date.now()) return null;
  return absence;
}

/**
 * The stand-in covering `userId` at `at`, or `null` when the member is not
 * away or named no delegate. One level only: the delegate is returned even
 * when that delegate is away too.
 */
export async function coveringDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence?.delegateUserId || !isAway(absence, at)) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;
  return absence.delegateUserId;
}

async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

function assertAbsenceWindow(startsAt: string, endsAt: string): void {
  const start = new Date(startsAt).getTime();
  const end = new Date(endsAt).getTime();
  if (!Number.isFinite(start) || !Number.isFinite(end) || !(end > start)) {
    throw new Error("Absence end must be after the start");
  }
}

/** Half-open window: the start counts, the end does not. */
function isAway(absence: MemberAbsence, at: Date): boolean {
  const start = new Date(absence.startsAt).getTime();
  const end = new Date(absence.endsAt).getTime();
  const t = at.getTime();
  return Number.isFinite(start) && Number.isFinite(end) && start <= t && t < end;
}

