/**
 * Where a new assignment to `requested` lands at this moment.
 *
 * An away member's work goes to their delegate, except when the actor is
 * assigning the issue to themselves. The delegate is used as-is: if they are
 * away too, the issue stays with them.
 */
async function assigneeForNewAssignment(
  orgId: OrgId,
  actorId: UserId,
  requested: UserId | null,
): Promise<UserId | null> {
  if (requested === null || requested === actorId) return requested;
  const delegate = await coveringDelegate(orgId, requested, new Date());
  return delegate ?? requested;
}

