/**
 * A mention of an away member also alerts their delegate. The original list
 * is what gets expanded, so a delegate's own absence is not followed unless
 * that delegate was mentioned directly. `notify` drops the author and keeps
 * one row per person.
 */
async function mentionRecipients(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  at: Date,
): Promise<UserId[]> {
  const recipients: UserId[] = [...mentionedUserIds];
  for (const userId of mentionedUserIds) {
    const delegate = await coveringDelegate(orgId, userId, at);
    if (delegate !== null) recipients.push(delegate);
  }
  return recipients;
}

