/**
 * Temporary coverage for out-of-office delegation. Deleted after the check.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { setAbsenceSchema } from "@/schemas/member";
import { emit } from "@/lib/event-bus";
import { toIsoTimestamp, type CommentId, type IsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const START = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
const END = "2026-07-01T00:00:00.000Z" as IsoTimestamp;
const DURING = new Date("2026-06-15T12:00:00.000Z");
const NOTE = "Out until July";

function absenceInput(
  tenant: Tenant,
  user: keyof Tenant["userIds"],
  overrides: Partial<{
    delegate: keyof Tenant["userIds"] | null;
    startsAt: IsoTimestamp;
    endsAt: IsoTimestamp;
    note: string | null;
  }> = {},
) {
  const delegate = overrides.delegate === undefined ? "admin" : overrides.delegate;
  return {
    orgId: tenant.org.id,
    userId: tenant.userIds[user],
    delegateUserId: delegate === null ? null : tenant.userIds[delegate],
    startsAt: overrides.startsAt ?? START,
    endsAt: overrides.endsAt ?? END,
    note: overrides.note === undefined ? NOTE : overrides.note,
  };
}

async function notifications(
  tenant: Tenant,
  recipient: keyof Tenant["userIds"],
  kind: "issue_assigned" | "issue_overdue" | "comment_mention",
) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: tenant.userIds[recipient],
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

beforeEach(() => {
  resetOverdueTracking();
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
  cleanup();
});

describe("absence behaviour", () => {
  it("parses the schema defaults", () => {
    const parsed = setAbsenceSchema.parse({
      orgId: "01HZZZGGGGGGGGGGGGGGGGGGGG",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      startsAt: START,
      endsAt: END,
    });
    expect(parsed.delegateUserId).toBeNull();
    expect(parsed.note).toBeNull();
    expect(setAbsenceSchema.safeParse({
      orgId: "01HZZZGGGGGGGGGGGGGGGGGGGG",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      startsAt: START,
      endsAt: END,
      note: "x".repeat(201),
    }).success).toBe(false);
  });

  it("sets, replaces, reads and clears an absence", async () => {
    const tenant = await createTenant("abs-crud");
    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { delegate: "admin" }),
    );
    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: START,
      endsAt: END,
      note: NOTE,
    });

    const again = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { delegate: null, note: "changed" }),
    );
    expect(again.delegateUserId).toBeNull();
    expect(again.note).toBe("changed");
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toEqual(again);

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
  });

  it("rejects a window that does not move forward and a self-delegate", async () => {
    const tenant = await createTenant("abs-validate");
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { startsAt: END, endsAt: START }),
      ),
    ).rejects.toThrow(/after the start/);
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { startsAt: START, endsAt: START }),
      ),
    ).rejects.toThrow(/after the start/);
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { delegate: "member" }),
      ),
    ).rejects.toThrow(/themselves/);
  });

  it("hides unknown members and refuses cross-tenant calls", async () => {
    const tenant = await createTenant("abs-scope");
    const other = await createTenant("abs-scope-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.admin,
        { ...absenceInput(tenant, "member"), userId: other.userIds.member },
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(
        tenant.actors.admin,
        { ...absenceInput(tenant, "member"), delegateUserId: other.userIds.admin },
