      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.admin);

    const seen: unknown[] = [];
    const off = subscribe("issue.assigned", (payload) => seen.push(payload));
    const detachAudit = registerActivityListeners();
    try {
      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, { title: "Reassign target" }),
      );
      const assigned = await issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      });
      expect(assigned.assigneeId).toBe(tenant.userIds.admin);
      expect(seen[0]).toMatchObject({ assigneeId: tenant.userIds.admin });

      const self = await issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      });
      expect(self.assigneeId).toBe(tenant.userIds.member);

      const alerts = await notifications(tenant, "admin", "issue_assigned");
      const missed = await notifications(tenant, "member", "issue_assigned");
      expect(alerts).toHaveLength(1);
      expect(missed).toHaveLength(0);
    } finally {
      off();
      detachAudit();
    }

    const plain = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "No delegate" }),
    );
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, "viewer", { delegate: null }),
    );
    const stayed = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: plain.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(stayed.assigneeId).toBe(tenant.userIds.viewer);
  });

